update t_sale_order_detail
order_id = #{orderId}, customer_id = #{customerId}, customer_dept_id = #{customerDeptId}, sku_id = #{skuId}, order_code = #{orderCode}, product_name = #{productName}, product_unit = #{productUnit}, product_price = #{productPrice}, product_spec = #{productSpec}, num = #{num}, expect_amount = #{expectAmount}, price_source = #{priceSource}, ref_price = #{refPrice}, price_reason = #{priceReason}, loss_reason = #{lossReason}, actual_price = #{actualPrice}, actual_num = #{actualNum}, actual_amount = #{actualAmount}, sort = #{sort}, change_type = #{changeType}, change_group = #{changeGroup}, change_remark = #{changeRemark}, is_deleted = #{isDeleted}, version = #{version}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
