mapper.select:
select d.id, d.order_id, d.customer_id, d.customer_dept_id, d.sku_id, d.order_code, d.product_name, d.product_unit, d.product_price, d.product_spec, d.num from t_sale_order_detail d where d.is_deleted = 0 and d.order_id in
#{orderId}
order by d.order_id, d.sort, d.id

select d.sku_id, d.product_name, d.product_unit, d.product_spec, coalesce(pc.name, '临时商品') as category_name, sum(d.num) as num, min(d.product_price) as product_price, sum(d.num * d.product_price) as expect_amount from t_sale_order_detail d inner join t_sale_order o on o.id = d.order_id left join t_product_sku ps on ps.id = d.sku_id left join t_product_category pc on pc.id = ps.category_id where o.id in
#{orderId}
and o.status = 1 and o.is_deleted = 0 and d.is_deleted = 0 group by d.sku_id, d.product_name, d.product_unit, d.product_spec, pc.name order by pc.name, d.product_name

select d.sku_id, max(d.product_name) as product_name, max(d.product_unit) as product_unit, max(d.product_spec) as product_spec, count(*) as order_count, date_format(max(d.create_time), '%Y-%m-%d %H:%i:%s') as last_order_time from t_sale_order_detail d inner join t_sale_order o on o.id = d.order_id where o.customer_id = #{customerId} and o.status > 0 and o.is_deleted = 0 and d.is_deleted = 0 and d.sku_id is not null and d.create_time >= #{startTime}
and exists (select 1 from customers_sku cs where cs.customer_id = o.customer_id and cs.sku_id = d.sku_id and cs.status = 1
and (cs.dept_id is null or cs.dept_id = #{deliveryPointId})
and cs.dept_id is null ) group by d.sku_id order by order_count desc, last_order_time desc limit #{limit}
